+                  values.is_contiguous(),
+              "n512 recertification inputs must be contiguous");
+  TORCH_CHECK(stage == 0 || stage == 1,
+              "n512 recertification stage must be zero or one");
+  const int batch = static_cast<int>(input.size(0));
+  TORCH_CHECK(batch > 0 && batch <= 1024,
+              "n512 recertification batch must be in [1, 1024]");
