+  auto gram = state.gram.narrow(0, 0, batch);
+  auto aq = state.aq.narrow(0, 0, batch);
+  auto flags = state.flags.narrow(0, 0, batch);
+  auto positions = state.positions.narrow(0, 0, batch);
+  torch::Tensor active_values = values;
+
+  at::bmm_out(gram, vectors.transpose(1, 2), vectors);
+  at::bmm_out(aq, input, vectors);
+  if (update_values) {
+    auto rayleigh_product = state.rayleigh_product.narrow(0, 0, batch);
+    active_values = state.values.narrow(0, 0, batch);
+    at::mul_out(rayleigh_product, vectors, aq);
