void ensure_recertification_state(
    RecertificationState& state, const torch::Tensor& input, int batch,
    bool need_rayleigh) {
  const int device = input.get_device();
  if (state.device != device) {
    state.device = device;
    state.capacity = 0;
    state.gram = torch::Tensor();
    state.aq = torch::Tensor();
    state.flags = torch::Tensor();
    state.rayleigh_product = torch::Tensor();
    state.values = torch::Tensor();
    state.positions = torch::Tensor();
  }
  if (state.capacity < batch) {
    state.capacity = batch;
    state.gram = torch::empty(
        {batch, 512, 512}, input.options());
    state.aq = torch::empty(
        {batch, 512, 512}, input.options());
    state.flags = torch::empty(
        {batch}, input.options().dtype(torch::kInt32));
    state.positions = torch::empty(
        {batch}, input.options().dtype(torch::kInt64));
    if (need_rayleigh) {
      state.rayleigh_product = torch::empty(
          {batch, 512, 512}, input.options());
      state.values = torch::empty({batch, 512}, input.options());
    }
  } else if (need_rayleigh && !state.rayleigh_product.defined()) {
    state.rayleigh_product = torch::empty(
        {state.capacity, 512, 512}, input.options());
    state.values = torch::empty(
        {state.capacity, 512}, input.options());
  }
  if (state.host_count == nullptr) {
    const cudaError_t allocation_status = cudaHostAlloc(
        reinterpret_cast<void**>(&state.host_count), sizeof(int),
        cudaHostAllocMapped);
    TORCH_CHECK(allocation_status == cudaSuccess,
                "recertification count allocation failed: ",
                cudaGetErrorString(allocation_status));
    const cudaError_t mapping_status = cudaHostGetDevicePointer(
        reinterpret_cast<void**>(&state.device_count), state.host_count, 0);
    TORCH_CHECK(mapping_status == cudaSuccess,
                "recertification count mapping failed: ",
                cudaGetErrorString(mapping_status));
  }
}

